import json
from pathlib import Path

import pytest

import risk.report_pipeline
from risk.report_pipeline import risk_report
from risk.types import Report

ROW_KEYS = {
    "ticker",
    "ann_return",
    "ann_vol",
    "sharpe",
    "last_vol",
    "max_drawdown",
    "peak_date",
    "trough_date",
}


@pytest.fixture
def fake_vol(monkeypatch: pytest.MonkeyPatch, contract_fake) -> None:
    fake = contract_fake("risk.vol_series")
    monkeypatch.setattr(risk.report_pipeline, "vol_series", fake.vol_series)


@pytest.mark.usefixtures("fake_vol")
def test_runs_end_to_end_with_output_shape(tmp_path: Path) -> None:
    out = tmp_path / "report.json"
    report = risk_report("ignored.csv", out, window=2)
    assert isinstance(report, Report)
    assert report.path == str(out)
    assert [row["ticker"] for row in report.rows] == ["AAA", "BBB"]
    for row in report.rows:
        assert set(row) == ROW_KEYS
    assert json.loads(out.read_text(encoding="utf-8")) == {"tickers": list(report.rows)}


@pytest.mark.usefixtures("fake_vol")
def test_tickers_narrow_the_report(tmp_path: Path) -> None:
